namespace sv_ceb9d76e1a164a00aec88cf0c426886d.Client.Models;

public sealed class Shipment
{
    public required string TrackingNumber { get; init; }
    public required string Status { get; init; }
    public required string Location { get; init; }
    public required DateTimeOffset EstimatedDelivery { get; init; }
    public required IReadOnlyList<StatusUpdate> StatusUpdates { get; init; }
}

public sealed class StatusUpdate
{
    public required DateTimeOffset Timestamp { get; init; }
    public required string Description { get; init; }
    public required string Location { get; init; }
}

using sv_ceb9d76e1a164a00aec88cf0c426886d.Client.Models;

namespace sv_ceb9d76e1a164a00aec88cf0c426886d.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;
using sv_ceb9d76e1a164a00aec88cf0c426886d.Client.Models;

namespace sv_ceb9d76e1a164a00aec88cf0c426886d.Client.Services;

/// <summary>
/// WASM-side implementation that calls the server API.
/// </summary>
public sealed class HttpShipmentService(HttpClient http) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

using sv_ceb9d76e1a164a00aec88cf0c426886d.Client.Models;
using sv_ceb9d76e1a164a00aec88cf0c426886d.Client.Services;

namespace sv_ceb9d76e1a164a00aec88cf0c426886d.Services;

/// <summary>
/// Server-side implementation that simulates a slow backend with seeded data.
/// </summary>
public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-1001"] = new Shipment
        {
            TrackingNumber = "PKG-1001",
            Status = "In Transit",
            Location = "Memphis, TN",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 12, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 7, 8, 30, 0, TimeSpan.Zero), Description = "Package picked up", Location = "Los Angeles, CA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 8, 14, 15, 0, TimeSpan.Zero), Description = "Departed facility", Location = "Los Angeles, CA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 9, 6, 45, 0, TimeSpan.Zero), Description = "Arrived at hub", Location = "Memphis, TN" },
            ]
        },
        ["PKG-2002"] = new Shipment
        {
            TrackingNumber = "PKG-2002",
            Status = "Out for Delivery",
            Location = "Seattle, WA",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 9, 20, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 6, 10, 0, 0, TimeSpan.Zero), Description = "Package picked up", Location = "Portland, OR" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 7, 9, 30, 0, TimeSpan.Zero), Description = "In transit", Location = "Tacoma, WA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 9, 7, 0, 0, TimeSpan.Zero), Description = "Out for delivery", Location = "Seattle, WA" },
            ]
        },
        ["PKG-3003"] = new Shipment
        {
            TrackingNumber = "PKG-3003",
            Status = "Delivered",
            Location = "New York, NY",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 8, 18, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 5, 12, 0, 0, TimeSpan.Zero), Description = "Package picked up", Location = "Chicago, IL" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 6, 22, 0, 0, TimeSpan.Zero), Description = "Arrived at hub", Location = "Columbus, OH" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 7, 16, 30, 0, TimeSpan.Zero), Description = "In transit", Location = "Philadelphia, PA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 7, 8, 11, 15, 0, TimeSpan.Zero), Description = "Delivered", Location = "New York, NY" },
            ]
        }
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate a slow backend
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

